with cleaned as (select *, round(quantity, 1) quantity_rounded from inventory where last_restock >= to_date('2024-04-20')) select date_trunc('week', last_restock) as week_start, case when quantity >= 206 then 'HIGH' else 'LOW' end as quantity_tier, round(avg(quantity), 2) as avg_quantity, percentile_approx(quantity_rounded, array(0.25, 0.5, 0.75)) as quantity_rounded_quartiles, min(quantity_rounded) as min_quantity_rounded, grouping(date_trunc('week', last_restock)) as grouping_level from cleaned group by grouping sets ((date_trunc('week', last_restock), case when quantity >= 206 then 'HIGH' else 'LOW' end), (date_trunc('week', last_restock))) having min(quantity_rounded) > 0;
